      },
      {
        "id": "personal-development-2",
        "module": 0,
        "title": "Watch: The power of vulnerability (Bren\u00e9 Brown, TED)",
        "type": "video",
        "url": "https://www.youtube.com/watch?v=iCvmsMzlF7o",
        "fileName": "",
        "body":
